import { readFileSync, writeFileSync, unlinkSync } from 'node:fs';

writeFileSync(
  'src/lib/priority-conclusion.ts',
  `import type { VerificationStatus } from "./comparison";\n\nexport type PriorityScore = 0 | 1 | 2;\nexport type PriorityOutcome = "standard" | "left" | "right" | "tie" | "unknown";\n\nexport interface PriorityEvaluation {\n  score?: PriorityScore;\n  status: VerificationStatus;\n  reason: string;\n}\n\nexport interface PriorityOption {\n  id: string;\n  label: string;\n  left: PriorityEvaluation;\n  right: PriorityEvaluation;\n  caution: string;\n  evidenceHref: \`#\${string}\`;\n}\n\nexport interface PriorityConclusion {\n  selectedId?: string;\n  outcome: PriorityOutcome;\n  heading: string;\n  summary: string;\n  reasons: readonly string[];\n  caution: string;\n  evidenceHref: \`#\${string}\`;\n}\n\nexport interface StandardPriorityConclusion {\n  heading: string;\n  summary: string;\n  caution: string;\n  evidenceHref: \`#\${string}\`;\n}\n\nconst isVerified = (evaluation: PriorityEvaluation): boolean =>\n  evaluation.status === "official" && evaluation.score !== undefined;\n\nexport function resolvePriorityConclusion(\n  selectedId: string | null | undefined,\n  options: readonly PriorityOption[],\n  labels: { left: string; right: string },\n  standard: StandardPriorityConclusion,\n): PriorityConclusion {\n  const option = options.find((candidate) => candidate.id === selectedId);\n  if (!option) {\n    return {\n      outcome: "standard",\n      heading: standard.heading,\n      summary: standard.summary,\n      reasons: [],\n      caution: standard.caution,\n      evidenceHref: standard.evidenceHref,\n    };\n  }\n\n  const reasons = [\n    \`\${labels.left}：\${option.left.reason}\`,\n    \`\${labels.right}：\${option.right.reason}\`,\n  ];\n  if (!isVerified(option.left) || !isVerified(option.right)) {\n    return {\n      selectedId: option.id,\n      outcome: "unknown",\n      heading: \`\${option.label}：判断材料不足\`,\n      summary: "確認済みの記事データだけでは一方を選べません。価格・在庫などは購入時点の販売ページで確認してください。",\n      reasons,\n      caution: option.caution,\n      evidenceHref: option.evidenceHref,\n    };\n  }\n  if (option.left.score === option.right.score) {\n    return {\n      selectedId: option.id,\n      outcome: "tie",\n      heading: \`\${option.label}：確認済みデータ上は同点\`,\n      summary: "この重視ポイントだけでは一方に絞れません。ほかの比較軸と実際の合いやすさも確認してください。",\n      reasons,\n      caution: option.caution,\n      evidenceHref: option.evidenceHref,\n    };\n  }\n  const leftWins = option.left.score > option.right.score;\n  const winner = leftWins ? labels.left : labels.right;\n  return {\n    selectedId: option.id,\n    outcome: leftWins ? "left" : "right",\n    heading: \`\${option.label}：\${winner}を先に確認\`,\n    summary: \`記事内で公式確認済みの項目では、\${winner}がこの重視ポイントに対応する機能を多く示しています。\`,\n    reasons,\n    caution: option.caution,\n    evidenceHref: option.evidenceHref,\n  };\n}\n\nexport function parsePriorityId(\n  params: URLSearchParams,\n  options: readonly PriorityOption[],\n): string | undefined {\n  const value = params.get("priority")?.normalize("NFKC").trim();\n  return value && options.some((option) => option.id === value) ? value : undefined;\n}\n`,
);

writeFileSync(
  'src/content/pampers-priorities.ts',
  `import type { PriorityOption, StandardPriorityConclusion } from "../lib/priority-conclusion";\n\nexport const pampersCandidateLabels = {\n  left: "肌へのいちばん",\n  right: "さらさらケア",\n} as const;\n\nexport const pampersStandardConclusion: StandardPriorityConclusion = {\n  heading: "標準の結論",\n  summary: "肌へのやさしさに関する公式機能を詳しく確認するなら「肌へのいちばん」、モレ・ムレ対策の公式機能を確認するなら「さらさらケア」から確認します。",\n  caution: "実際の合いやすさは赤ちゃんの体型や肌状態でも変わるため、少量から試してください。",\n  evidenceHref: "#comparison-details",\n};\n\nexport const pampersPriorityOptions: readonly PriorityOption[] = [\n  {\n    id: "skin-care",\n    label: "肌への配慮に関する公式機能",\n    left: { score: 2, status: "official", reason: "ワセリン配合シート、ふかふか肌ざわり、ゆるうんちの肌残りを抑える設計が案内されています" },\n    right: { score: 1, status: "official", reason: "吸収体とムレ対策の機能が案内されています" },\n    caution: "機能表示は肌トラブルが起きないことを保証するものではありません。",\n    evidenceHref: "#comparison-details",\n  },\n  {\n    id: "leak-fit",\n    label: "モレ・フィット対策の公式機能",\n    left: { score: 1, status: "official", reason: "ゆるうんちを素早く吸収する機能が案内されています" },\n    right: { score: 2, status: "official", reason: "360°ゆるうんちモレガードとのびのびフィットテープが案内されています" },\n    caution: "モレにくさは体型、装着方法、交換間隔でも変わります。",\n    evidenceHref: "#comparison-details",\n  },\n  {\n    id: "newborn-size",\n    label: "新生児サイズ",\n    left: { score: 1, status: "official", reason: "新生児5kgまでが掲載され、小さめ新生児3,000gも案内されています" },\n    right: { score: 1, status: "official", reason: "新生児5kgまでが掲載されています" },\n    caution: "同じ体重でも体型によって合いやすさは異なります。",\n    evidenceHref: "#comparison-details",\n  },\n  {\n    id: "price",\n    label: "価格",\n    left: { status: "unverified", reason: "価格は販売ページで確認が必要です" },\n    right: { status: "unverified", reason: "価格は販売ページで確認が必要です" },\n    caution: "価格・送料・ポイント・在庫は変動するため、記事の固定評価には使用しません。",\n    evidenceHref: "#comparison-details",\n  },\n];\n`,
);

writeFileSync(
  'src/components/PriorityConclusion.astro',
  `---\nimport type { PriorityOption, StandardPriorityConclusion } from '../lib/priority-conclusion';\n\ninterface Props {\n  options: readonly PriorityOption[];\n  labels: { left: string; right: string };\n  standard: StandardPriorityConclusion;\n}\nconst { options, labels, standard } = Astro.props;\nconst serialized = JSON.stringify({ options, labels, standard }).replaceAll('<', '\\u003c');\n---\n<section class="priority-conclusion" aria-labelledby="priority-conclusion-heading" data-priority-conclusion>\n  <p class="section-label">重視ポイントで確認</p>\n  <h2 id="priority-conclusion-heading">条件に応じた比較結論</h2>\n  <fieldset class="priority-options">\n    <legend>重視するポイント</legend>\n    <label><input type="radio" name="priority" value="" checked /> 標準</label>\n    {options.map((option) => <label><input type="radio" name="priority" value={option.id} /> {option.label}</label>)}\n  </fieldset>\n  <div class="card priority-result" role="status" aria-live="polite" aria-atomic="true">\n    <h3 data-priority-heading>{standard.heading}</h3>\n    <p data-priority-summary>{standard.summary}</p>\n    <ul hidden data-priority-reasons></ul>\n    <p class="notice" data-priority-caution>{standard.caution}</p>\n    <a href={standard.evidenceHref} data-priority-evidence>根拠となる比較表を確認する →</a>\n  </div>\n  <noscript><p class="notice">JavaScriptが無効な場合は標準の結論を表示します。下の比較表ですべての確認済み情報を確認できます。</p></noscript>\n  <script type="application/json" data-priority-data set:html={serialized} />\n</section>\n\n<script>\n  import { parsePriorityId, resolvePriorityConclusion } from '../lib/priority-conclusion';\n  import type { PriorityOption, StandardPriorityConclusion } from '../lib/priority-conclusion';\n\n  document.querySelectorAll('[data-priority-conclusion]').forEach((root) => {\n    if (!(root instanceof HTMLElement) || root.dataset.priorityBound === 'true') return;\n    root.dataset.priorityBound = 'true';\n    const dataNode = root.querySelector('[data-priority-data]');\n    if (!(dataNode instanceof HTMLScriptElement)) return;\n    const payload = JSON.parse(dataNode.textContent || '{}') as { options: PriorityOption[]; labels: { left: string; right: string }; standard: StandardPriorityConclusion };\n    const heading = root.querySelector('[data-priority-heading]');\n    const summary = root.querySelector('[data-priority-summary]');\n    const reasons = root.querySelector('[data-priority-reasons]');\n    const caution = root.querySelector('[data-priority-caution]');\n    const evidence = root.querySelector('[data-priority-evidence]');\n    const radios = [...root.querySelectorAll('input[name="priority"]')].filter((node): node is HTMLInputElement => node instanceof HTMLInputElement);\n    const render = (selectedId?: string) => {\n      const result = resolvePriorityConclusion(selectedId, payload.options, payload.labels, payload.standard);\n      if (heading) heading.textContent = result.heading;\n      if (summary) summary.textContent = result.summary;\n      if (caution) caution.textContent = result.caution;\n      if (evidence instanceof HTMLAnchorElement) evidence.href = result.evidenceHref;\n      if (reasons instanceof HTMLUListElement) {\n        reasons.replaceChildren(...result.reasons.map((reason) => { const item = document.createElement('li'); item.textContent = reason; return item; }));\n        reasons.hidden = result.reasons.length === 0;\n      }\n      radios.forEach((radio) => { radio.checked = radio.value === (result.selectedId || ''); });\n      const params = new URLSearchParams(location.search);\n      if (result.selectedId) params.set('priority', result.selectedId); else params.delete('priority');\n      history.replaceState(null, '', location.pathname + (params.size ? '?' + params.toString() : '') + location.hash);\n    };\n    const initial = parsePriorityId(new URLSearchParams(location.search), payload.options);\n    radios.forEach((radio) => radio.addEventListener('change', () => render(radio.value || undefined)));\n    render(initial);\n  });\n</script>\n`,
);

